Here is a complete C++ program that takes voltage and current as input, calculates the power and resistance, and displays the results.

The program uses the following fundamental physics formulas:
*   **Power ($P$):** $P = V \times I$
*   **Resistance ($R$):** $R = V / I$

### C++ Code

```cpp
#include <iostream>
#include <iomanip> // For setting decimal precision

int main() {
    double voltage;
    double current;
    double power;
    double resistance;

    // 1. Prompt the user for input
    std::cout << "Enter Voltage (V) in Volts: ";
    std::cin >> voltage;

    std::cout << "Enter Current (I) in Amperes: ";
    std::cin >> current;

    // 2. Basic Validation (Prevent division by zero)
    if (current == 0) {
        std::cout << "Error: Current cannot be zero. Cannot calculate resistance." << std::endl;
        // We can still calculate power if voltage is known (0 current -> 0 power usually, 
        // unless there is an open circuit with source voltage, but typically power is 0).
        if (voltage == 0) {
            power = 0.0;
        } else {
            power = voltage * current; 
        }
        std::cout << "Power (P): " << power << " Watts" << std::endl;
        return 0;
    }

    // 3. Perform Calculations
    // P = V * I
    power = voltage * current;

    // R = V / I
    resistance = voltage / current;

    // 4. Display Results
    std::cout << std::fixed << std::setprecision(2); // Set to 2 decimal places
    std::cout << "\n--- Results ---" << std::endl;
    std::cout << "Power (P) = " << power << " Watts (W)" << std::endl;
    std::cout << "Resistance (R) = " << resistance << " Ohms (Ω)" << std::endl;

    return 0;
}
```

